    # Find separator color and separator rows/cols:
    # rows/cols entirely filled with the same non-zero color.
    sep_color = None
    sep_rows = []
    for r in range(h):
        vals = set(grid[r])
        if len(vals) == 1:
            v = grid[r][0]
            if v != 0:
                sep_rows.append(r)
                if sep_color is None:
                    sep_color = v

    sep_cols = []
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            v = grid[0][c]
            if v != 0:
                sep_cols.append(c)
                if sep_color is None:
                    sep_color = v

    # Build row/col blocks between separators.
    row_blocks = []
    start = 0
    for r in sep_rows + [h]:
        if start < r:
            row_blocks.append((start, r))
        start = r + 1

    col_blocks = []
    start = 0
    for c in sep_cols + [w]:
        if start < c:
            col_blocks.append((start, c))
        start = c + 1

    nr, nc = len(row_blocks), len(col_blocks)

    # Copy grid
    out = [row[:] for row in grid]

    # Gather non-empty cell patterns (all non-zero, non-separator pixels inside blocks)
    sources = []
    for i, (r0, r1) in enumerate(row_blocks):
        for j, (c0, c1) in enumerate(col_blocks):
            pts = []
            for r in range(r0, r1):
                for c in range(c0, c1):
                    v = grid[r][c]
                    if v != 0 and v != sep_color:
                        pts.append((r - r0, c - c0))
            if pts:
                sources.append((i, j, pts))

    # Copy each source pattern to cells aligned by row, column, or diagonal
    for si, sj, pts in sources:
        for ti, (tr0, tr1) in enumerate(row_blocks):
            for tj, (tc0, tc1) in enumerate(col_blocks):
                if not (ti == si or tj == sj or (ti - si) == (tj - sj) or (ti - si) == -(tj - sj)):
                    continue
                for dr, dc in pts:
                    r = tr0 + dr
                    c = tc0 + dc
                    if tr0 <= r < tr1 and tc0 <= c < tc1 and out[r][c] == 0:
                        out[r][c] = sep_color

    return out

